import React from 'react';
import Section from '../components/Section';

const SupportPage = ({ user }) => (
  <div className="container mx-auto px-4 py-8">
    <Section title="Support & Feedback">
      <p className="text-gray-700 dark:text-gray-300">
        For questions, feedback, or support with MyESH, please contact our team via the following methods:
      </p>
      <ul className="list-disc list-inside mt-4 text-gray-600 dark:text-gray-400">
        <li>Email: support@myesh.africa</li>
        <li>Phone: +254 700 000 000</li>
        <li>Visit: County Agricultural Office, Wote</li>
      </ul>
    </Section>
  </div>
);

export default SupportPage;
